import { asFlag, useSearchParam } from '../../url/useSearchParam';

/** Whether retired people are listed. Off when the screen is first opened; kept in the URL, so
 *  loading a sheet leaves it as it is. */
export function useShowRetired() {
  return useSearchParam('retired', asFlag);
}

/** The "show retired" toggle above the people list. */
export function ShowRetired() {
  const [on, setOn] = useShowRetired();
  return (
    <label>
      <input
        type="checkbox"
        data-testid="show-retired"
        checked={on}
        onChange={(e) => setOn(e.target.checked ? true : undefined)}
      />{' '}
      Show retired
    </label>
  );
}
import { useState } from 'react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { postJson } from '../../api/http';
import { PersonCells, PersonColumns } from '../../slots/defs/personRow';
import { claimsKey } from '../claims/useClaims';
import { peopleKey, type Person } from '../people/usePeople';
import { useRowAction } from '../people/useRowAction';

/**
 * A person's statements: the button to take one, which records their due-total now and binds each
 * of their counting claims to the figure it has now (the rest are unbound), how many have been
 * taken, and the last one's due-total and date (blank when none has been taken). A date beside the
 * button takes it as of that date (on or before the sheet's today): the claims that counted at the
 * end of it are bound to their figures as they stood then, and the statement is dated it. A steward can
 * cancel the last statement: the claims it bound become live again, and the row shows the one
 * before it (or nothing).
 */
function PersonStatement({ user, sheet, person }: { user: string; sheet: string; person: Person }) {
  const queryClient = useQueryClient();
  const [asOf, setAsOf] = useState('');
  const take = useMutation({
    mutationFn: (date: string) =>
      postJson<Person>(`/api/sheets/${encodeURIComponent(sheet)}/people/${person.id}/statement`, { user, asOf: date }),
    // Taken or refused, the date is spent: the next press takes it as of a date only when one is typed again.
    onSettled: () => {
      setAsOf('');
      return Promise.all([
        queryClient.invalidateQueries({ queryKey: peopleKey(sheet) }),
        queryClient.invalidateQueries({ queryKey: claimsKey(sheet) }),
      ]);
    },
  });
  const cancel = useMutation({
    mutationFn: () =>
      postJson<Person>(`/api/sheets/${encodeURIComponent(sheet)}/people/${person.id}/unstate`, { user }),
    onSettled: () =>
      Promise.all([
        queryClient.invalidateQueries({ queryKey: peopleKey(sheet) }),
        queryClient.invalidateQueries({ queryKey: claimsKey(sheet) }),
      ]),
  });
  const actionTaken = useRowAction(sheet, person.id, () => {
    take.reset();
    cancel.reset();
  });
  const taken = person.statementCount > 0;
  return (
    <>
      <td data-testid="person-statement-count">{person.statementCount}</td>
      <td data-testid="person-stated-total">{taken ? (person.statedTotal ?? 'n/a') : ''}</td>
      <td data-testid="person-statement-date">{taken ? (person.statementDate ?? '') : ''}</td>
      <td>
        <input
          type="text"
          placeholder="as of yyyy-mm-dd"
          data-testid="person-statement-asof"
          value={asOf}
          onChange={(e) => {
            setAsOf(e.target.value);
            take.reset();
          }}
        />{' '}
        <button type="button" data-testid="person-statement" disabled={take.isPending} onClick={() => {
            actionTaken();
            cancel.reset();
            take.mutate(asOf);
          }}>
          Statement
        </button>
        <button type="button" data-testid="person-unstate" disabled={cancel.isPending} onClick={() => {
            actionTaken();
            take.reset();
            cancel.mutate();
          }}>
          Cancel statement
        </button>
        {take.isError && (
          <span data-testid="person-error" role="alert">
            {' '}
            Could not take this statement.
  const since = backingSince(today);
  const figure = (id: number) =>
    all
      .filter((c) => c.personId === id && c.status === 'SETTLED' && c.due !== null)
      .filter((c) => c.date >= since && c.date <= today)
      .reduce((sum, c) => sum + hundredths(c.due!), 0n);
  // figure (hundredths) × share (hundredths) is in millionths of the share-weighted sum; ÷ 10000.
  const backing = divHalfEven(
    named.reduce((sum, id) => sum + figure(id) * shareOf.get(id)!, 0n),
    10_000n,
  );

  const add = useMutation({
    mutationFn: (patronId: number) =>
      postJson<Person>(`/api/sheets/${encodeURIComponent(sheet)}/people/${person.id}/patrons`, { patronId, user }),
    onSuccess: () => setChosen(''),
    onSettled: () => queryClient.invalidateQueries({ queryKey: peopleKey(sheet) }),
  });

  return (
    <>
      <td data-testid="person-patrons">{labels.join(', ')}</td>
      <td data-testid="person-backing">{totalDue([backing])}</td>
      <td>
        <select
          data-testid="person-patron-select"
          value={chosen}
          onChange={(e) => {
            add.reset();
            setChosen(e.target.value);
          }}
        >
          <option value="">Choose a patron…</option>
          {people
            .filter((p) => p.id !== person.id)
            .map((p) => (
              <option key={p.id} value={String(p.id)}>
                {p.name}
              </option>
            ))}
        </select>
        <button
          type="button"
          data-testid="person-patron-add"
          disabled={add.isPending || chosen === ''}
          onClick={() => {
            add.reset();
            add.mutate(Number(chosen));
          }}
        >
          Add patron
import { useState } from 'react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { postJson } from '../../api/http';
import { PersonCells, PersonColumns } from '../../slots/defs/personRow';
import { peopleKey, type Person } from '../people/usePeople';
import { useRowAction } from '../people/useRowAction';

/**
 * A person's aliases (sorted as names are compared, comma and space separated), and the entry and
 * button to add one, and whether the person clashes with the sheet's tree. Aliases share the names'
 * uniqueness: the server refuses a blank alias and one equal, as names are compared, to any name or
 * alias on the sheet or on another sheet of its tree (its ancestors and descendants).
 */
function PersonAliases({ user, sheet, person }: { user: string; sheet: string; person: Person }) {
  const queryClient = useQueryClient();
  const [alias, setAlias] = useState('');
  const add = useMutation({
    mutationFn: (a: string) =>
      postJson<Person>(`/api/sheets/${encodeURIComponent(sheet)}/people/${person.id}/aliases`, { alias: a, user }),
    onSuccess: () => setAlias(''),
    onSettled: () => queryClient.invalidateQueries({ queryKey: peopleKey(sheet) }),
  });
  const actionTaken = useRowAction(sheet, person.id, add.reset);
  return (
    <>
      <td data-testid="person-clashing">{person.clashing ? 'yes' : 'no'}</td>
      <td data-testid="person-aliases">{person.aliases.join(', ')}</td>
      <td>
        <input
          type="text"
          placeholder="alias"
          data-testid="person-alias-input"
          value={alias}
          onChange={(e) => {
            setAlias(e.target.value);
            add.reset();
          }}
        />{' '}
        <button
          type="button"
          data-testid="person-alias-add"
          disabled={add.isPending}
          onClick={() => {
            actionTaken();
            add.reset();
            add.mutate(alias);
          }}
        >
          Add alias
        </button>
        {add.isError && (
          <span data-testid="person-error" role="alert">
            {' '}
            Could not add this alias (not blank, and not a name or alias already on the sheet or its tree).
          </span>
        )}
      </td>
    </>
  );
}

export const contributions = [
  PersonColumns.fill({
    order: 5,
    Component: () => (
      <>
        <th>Clashing</th>
        <th>Aliases</th>
        <th />
      </>
    ),
  }),
  PersonCells.fill({ order: 5, Component: PersonAliases }),
];
  const unretire = useMutation({
    mutationFn: () =>
      postJson<Person>(`/api/sheets/${encodeURIComponent(sheet)}/people/${person.id}/unretire`, { user }),
    onSettled: () =>
      Promise.all([
        queryClient.invalidateQueries({ queryKey: peopleKey(sheet) }),
        queryClient.invalidateQueries({ queryKey: poolsKey(sheet) }),
      ]),
  });
  const actionTaken = useRowAction(sheet, person.id, () => {
    retire.reset();
    unretire.reset();
  });
  return (
    <>
      <td data-testid="person-retired">{person.retired ? 'yes' : 'no'}</td>
      <td data-testid="person-retired-from">{person.retiredFrom ?? ''}</td>
      <td>
        {person.pastRetirements.map((r, i) => (
          <div key={i} data-testid="person-retirement-line">
            {r.from} to {r.to}
          </div>
        ))}
      </td>
      <td>
        <input
          type="text"
          placeholder="yyyy-mm-dd"
          data-testid="person-retire-date"
          value={from}
          onChange={(e) => {
            setFrom(e.target.value);
            retire.reset();
            unretire.reset();
          }}
        />{' '}
        <button
          type="button"
          data-testid="person-retire"
